import {MATERIALS,RECIPES,MAX_LEVEL} from './catalog.mjs';
import {Run,gunStats} from './model.mjs';
import {Renderer} from './render.mjs';
const $=id=>document.getElementById(id);
export const run=new Run();
const renderer=new Renderer($('arena'));
let keys={},joy={x:0,y:0},pointer=null,last=0,phase='',inventorySignature='',selected='water',pending=null,dialogType=null,resumeAfterLog=false,previousFocus=null,sound=false,audio,toastUntil=0;
const gunName=()=>run.lab.gun.type==='normal'?'普通枪':RECIPES[run.lab.gun.type].name;
const stockText=stock=>Object.entries(stock).filter(([,n])=>n>0).map(([id,n])=>`${MATERIALS[id].formula} ×${n}`).join(' · ')||'无';
function beep(hz,seconds=.06,type='sine',volume=.018){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume?.();const o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.value=hz;v.gain.setValueAtTime(volume,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+seconds);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+seconds)}catch{}}
function clearInput(){keys={};joy={x:0,y:0};pointer=null;$('stick').style.transform='translate(0,0)'}
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');toastUntil=performance.now()+2100}
function start(){clearInput();closeDialog(false);run.start();phase='';inventorySignature='';last=performance.now();sync();$('arena').focus({preventScroll:true});beep(330,.12)}
function pause(){if(dialogType)return;if(run.state==='playing'){run.state='paused';clearInput()}else if(run.state==='paused'){run.state='playing';last=performance.now()}sync()}
function menu(){clearInput();run.reset();phase='';sync()}
function syncBag(){const enabled=run.state==='lab';const sig=JSON.stringify([run.lab.inventory,enabled]);if(sig===inventorySignature)return;inventorySignature=sig;$('materialCards').innerHTML=Object.entries(MATERIALS).map(([id,m])=>`<button class="material-card" data-add="${id}" draggable="${enabled&&run.lab.inventory[id]>0}" style="--material:${m.color}" aria-label="${enabled?'向炉内加入':'背包'}${m.name}，当前${run.lab.inventory[id]}份" ${!enabled||!run.lab.inventory[id]?'disabled':''}><span class="material-icon">${m.formula}</span><span class="material-copy"><b>${m.name}</b><small>${m.label}${enabled?' · 点击投料':''}</small></span><span class="material-count"><small>×</small>${run.lab.inventory[id]}</span></button>`).join('');$('inventoryTotal').textContent=`${Object.values(run.lab.inventory).reduce((a,b)=>a+b,0)} 份`;$('bagHint').textContent=enabled?'拖到炉内或点击投料；炉内物质点击可取回。':'击败怪物，靠近拾取。波末自动回收。'}
function syncGun(){const gun=run.lab.gun,s=gunStats(gun),recipe=RECIPES[gun.type];$('gunName').textContent=gunName();$('gunLevel').textContent=gun.type==='normal'?'基础型 / LV. 0':`${recipe.family} / LV. ${gun.level}`;$('gunIcon').style.color=recipe?.color||'#a9bda0';$('statDamage').textContent=s.damage;$('statRate').textContent=`${(1/s.interval).toFixed(1)}/s`;$('statBurn').textContent=s.burnDps?`${s.burnDps}/s`:'—';$('gunDescription').textContent=recipe?recipe.effect:'一把可靠的普通枪。先活下来，再想办法变强。'}
function syncRecipes(){const isLab=run.state==='lab';$('recipeCards').innerHTML=Object.entries(RECIPES).map(([id,r])=>{const affordable=Object.entries(r.cost).every(([k,n])=>run.lab.inventory[k]+run.lab.furnace[k]>=n);return `<button class="recipe-card ${id===selected?'selected':''}" data-recipe="${id}" ${!isLab?'disabled':''}><div class="recipe-head"><b>${r.name}</b><span class="${id==='flame'?'flame-tag':''}">${r.tag}</span></div><p>${stockText(r.cost)}</p><small>${isLab?(affordable?'材料充足 · 点击选择':'材料不足 · 仍可查看配方'):'波间实验室可改装'}</small></button>`}).join('')}
function syncLab(){syncBag();syncGun();syncRecipes();const l=run.lab,r=RECIPES[selected],info=l.recipeInfo(selected);$('furnaceContents').innerHTML=Object.entries(l.furnace).filter(([,n])=>n>0).map(([id,n])=>`<button class="furnace-chip" data-remove="${id}" draggable="true" aria-label="取回一份${MATERIALS[id].name}">${MATERIALS[id].formula} ×${n}<span>−</span></button>`).join('')||'<span class="empty-furnace">炉内空空的，先加点材料吧。</span>';$('recipeKind').textContent=r.tag;$('recipeTitle').textContent=r.name;$('recipeNumber').textContent=selected==='water'?'H₂O':'H₂ + O₂';$('equation').textContent=r.equation||'装填水 → 水枪模块';$('scienceNote').textContent=r.fact+(selected==='flame'?' 产水进入实验收集瓶，不回流可用背包。':'');$('furnaceSymbol').textContent=selected==='water'?'H₂O':'H₂';$('reactorLevel').textContent=l.gun.type===selected?l.gun.level+1:1;$('ignition').checked=l.ignition;$('ignition').disabled=selected!=='flame';const missing=stockText(info.missing);$('requirements').classList.toggle('missing',!info.ready||selected==='flame'&&!l.ignition);$('requirements').textContent=!info.ready?`炉内还缺：${missing}`:selected==='flame'&&!l.ignition?'需要开启炉内点火源':'炉内配方就绪 · 多余材料自动退回';$('craft').disabled=!info.ready||selected==='flame'&&!l.ignition;$('craft').innerHTML=`${l.gun.type===selected?'同系增强':info.replace?'替换为':'制作'}${r.name}${l.gun.type===selected?` · Lv.${l.gun.level+1}`:''} <span>↗</span>`;$('nextWave').disabled=l.gun.type==='normal';$('nextWave').innerHTML=l.gun.type==='normal'?'先完成一次改装，再进入第二波 <span>→</span>':'装备就绪，开始第二波 <span>→</span>';$('returnAll').disabled=Object.values(l.furnace).every(n=>n===0);$('supplyNote').classList.remove('hidden');$('supplyNote').textContent=Object.values(run.supply).some(n=>n>0)?`首波教学补给：${stockText(run.supply)}。场上物质已自动回收。`:'场上物质已自动回收，库存已足够改装。';$('scienceTip').textContent=selected==='water'?MATERIALS.water.fact:MATERIALS.oxygen.fact;if(info.maxed){$('craft').disabled=true;$('craft').textContent=`已达本原型上限 · Lv.${MAX_LEVEL}`;$('requirements').textContent='本系已满级，不再消耗材料；可退回材料或改选另一系。';$('requirements').classList.remove('missing');$('reactorLevel').textContent=MAX_LEVEL}}
function move(id,to){if(run.state!=='lab'||dialogType)return;if(run.lab.moveMaterial(id,to)){syncLab();beep(to==='furnace'?460:300,.04)}}
function requestCraft(){if(run.state!=='lab'||dialogType)return;let result=run.craft(selected);if(result.reason==='replace'){pending=selected;showDialog('replace',`<div class="eyebrow">RECONFIGURE / 异系替换</div><h2>换一个方向，重新开始。</h2><p>当前 <strong>${gunName()} Lv.${run.lab.gun.level}</strong> 将被替换为 <strong>${RECIPES[pending].name} Lv.1</strong>。旧系强化清零，材料不返还。</p><p>确认后才会扣除炉内的配方材料；取消会保留所有材料。</p><button class="primary" id="confirmReplace">确认替换并清零 <span>→</span></button><button class="cancel" id="cancelDialog">保留当前装备</button>`);$('confirmReplace').onclick=()=>{const id=pending;closeDialog(false);completeCraft(run.craft(id,true),id)};$('cancelDialog').onclick=()=>closeDialog();return}completeCraft(result,selected)}
function completeCraft(result,id){if(!result.ok){$('labFeedback').textContent='条件尚未满足，请检查炉内材料和点火源。';return}beep(660,.16);const r=RECIPES[id];$('labFeedback').textContent=`${r.name} Lv.${run.lab.gun.level} 已就绪。${id==='flame'?'反应产水 2 份已记入收集瓶。':''}剩余材料已退回背包。`;syncLab()}
function showDialog(type,html){previousFocus=document.activeElement;dialogType=type;$('dialogCard').innerHTML=html;$('dialogOverlay').classList.remove('hidden');$('dialogCard').querySelector('button')?.focus({preventScroll:true})}
function closeDialog(restore=true){$('dialogOverlay').classList.add('hidden');if(dialogType==='log'&&resumeAfterLog){run.state='playing';last=performance.now()}resumeAfterLog=false;dialogType=null;pending=null;if(restore)previousFocus?.focus?.({preventScroll:true});sync()}
function openLog(){if(dialogType)return;resumeAfterLog=run.state==='playing';if(resumeAfterLog){run.state='paused';clearInput();sync()}showDialog('log',`<div class="eyebrow">DISCOVERY LOG / 本局图鉴</div><h2>把发现，留在这里。</h2>${Object.entries(MATERIALS).map(([id,m])=>`<div class="log-entry"><h3>${m.formula} · ${m.name}</h3><p>${m.fact}</p></div>`).join('')}<div class="log-entry"><h3>本局已制作</h3><p>${run.lab.discoveries.length?run.lab.discoveries.map(id=>RECIPES[id].name).join('、'):'尚未完成改装；第一波结束后进入实验室。'}</p></div>${run.lab.discoveries.includes('flame')?`<div class="log-entry"><h3>氢气燃烧 · 已发现</h3><p class="formula">2H₂ + O₂ → 2H₂O</p><p>条件：点火。氧气是氧化剂，空气中也存在氧气。试验产水累计 ${run.lab.products.water} 份，仅作收集记录。</p></div>`:''}<div class="log-entry"><h3>化学事实与游戏效果</h3><p>水枪攻速、持续灼烧、材料换取模块与不限弹药均属于游戏机制；不代表物质的全部现实性质或实际实验操作。隐藏配方后续加入。</p></div><button class="cancel" id="cancelDialog">返回${resumeAfterLog?'战斗':'实验'}</button>`);$('cancelDialog').onclick=()=>closeDialog()}
function sync(){const state=run.state,lab=state==='lab';$('hpText').textContent=`${run.hp} / 100`;$('hpBar').style.width=`${run.hp}%`;$('kills').textContent=run.kills;$('waveLabel').textContent=String(run.wave).padStart(2,'0');const t=Math.max(0,Math.ceil(60-run.waveTime));$('timer').textContent=lab?'LAB':`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;$('phaseLabel').textContent=({menu:'准备实验',playing:run.wave===1?'收集阶段':'改装验证',lab:'波间实验室',paused:'实验暂停',dead:'实验中止',won:'实验完成'})[state];$('phaseDot').style.background=lab?'#77d9f5':state==='dead'?'#ed8e92':'#b9e4ad';$('pause').disabled=!['playing','paused'].includes(state);$('pause').textContent=state==='paused'?'▷':'Ⅱ';$('pause').setAttribute('aria-label',state==='paused'?'继续游戏':'暂停游戏');syncBag();if(phase===state)return;phase=state;clearInput();$('labView').classList.toggle('hidden',!lab);$('stage').classList.toggle('lab-stage',lab);$('battleHud').classList.toggle('hidden',lab);$('controlsNote').classList.toggle('hidden',lab);$('screenOverlay').classList.toggle('hidden',!['menu','paused','dead','won'].includes(state));$('fieldHint').textContent=lab?'材料不会凭空消失：制作只消耗配方所需，多余退回。':run.wave===1?'第一波收集物质，结束后进入实验室。':'水蓝弹提高射速，淡蓝火焰附加持续灼烧。';syncGun();syncRecipes();if(lab){selected='water';$('labFeedback').textContent='先选择右侧配方，再从背包投料。';syncLab();$('furnace').focus({preventScroll:true});return}if(state==='playing'){$('supplyNote').classList.add('hidden');return}const card=$('screenCard');if(state==='menu'){card.innerHTML='<div class="eyebrow">AN EXPERIMENT IN SURVIVAL</div><h2>一把枪。<br>新的<span>可能。</span></h2><p>先用普通枪收集物质，再到实验室改装。<br>你的配方，将决定下一波的战斗方式。</p><div class="start-steps"><span><b>01</b> 收集物质</span><i>→</i><span><b>02</b> 拖拽改装</span><i>→</i><span><b>03</b> 验证火力</span></div><button id="start" class="primary">开始实验 <span>↗</span></button><div class="start-tip">按 Enter 开始 · 两波各 60 秒 · 无需下载</div>';$('start').onclick=start}else if(state==='paused'){card.innerHTML='<div class="eyebrow">EXPERIMENT PAUSED</div><h2>暂停一下，<br>思路<span>继续。</span></h2><p>实验现场已暂停，准备好后继续。</p><button id="resume" class="primary">继续实验 <span>▷</span></button><button id="back" class="back-link">返回主菜单</button>';$('resume').onclick=pause;$('back').onclick=menu}else if(['dead','won'].includes(state)){const won=state==='won';card.innerHTML=`<div class="eyebrow">${won?'EXPERIMENT COMPLETE':'TRY ANOTHER HYPOTHESIS'}</div><h2>${won?'你的配方，<br><span>经得起考验。</span>':'这次倒下，<br><span>下次换个配方。</span>'}</h2><div class="result-stats"><div><b>${Math.round(run.elapsed)}s</b><small>生存时间</small></div><div><b>${run.kills}</b><small>清除目标</small></div><div><b>${Math.round(run.damageDone)}</b><small>总伤害</small></div></div><div class="result-gun">${gunName()} Lv.${run.lab.gun.level} · ${run.lab.gun.type==='flame'?`灼烧伤害 ${Math.round(run.burnDamage)}`:`射速 ${(1/gunStats(run.lab.gun).interval).toFixed(1)}/s`}</div><p>${won?'下一次，试试另一种化学选择。':'物质与强化在重开时重置，重新验证你的选择。'}</p><button id="restart" class="primary">再做一次实验 <span>↻</span></button><button id="back" class="back-link">返回主菜单</button>`;$('restart').onclick=start;$('back').onclick=menu}card.querySelector('button')?.focus({preventScroll:true})}
$('materialCards').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)move(b.dataset.add,'furnace')});$('furnaceContents').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b)move(b.dataset.remove,'inventory')});$('recipeCards').addEventListener('click',e=>{const b=e.target.closest('[data-recipe]');if(b&&run.state==='lab'&&!dialogType){selected=b.dataset.recipe;syncLab()}});
$('returnAll').onclick=()=>{if(run.state==='lab'&&!dialogType){run.lab.returnAll();syncLab()}};$('craft').onclick=requestCraft;$('nextWave').onclick=()=>{if(dialogType)return;const hp=run.hp;if(run.nextWave()){clearInput();sync();toast(`${gunName()} Lv.${run.lab.gun.level} · 第二波开始 · 生命补给 +${run.hp-hp}`);$('arena').focus({preventScroll:true})}};$('ignition').onchange=()=>{if(run.state==='lab'&&!dialogType){run.lab.ignition=$('ignition').checked;syncLab()}};$('pause').onclick=pause;$('openLog').onclick=openLog;$('sound').onclick=()=>{sound=!sound;$('soundOff').classList.toggle('hidden',sound);$('sound').setAttribute('aria-label',sound?'关闭音效':'开启音效');beep(440,.1)};
function dragStart(e,selector,from){const b=e.target.closest(selector);if(!b||run.state!=='lab'||dialogType){e.preventDefault();return}const id=b.dataset.add||b.dataset.remove;e.dataTransfer.setData('application/x-valence',JSON.stringify({id,from}));e.dataTransfer.effectAllowed='move'}
$('materialCards').addEventListener('dragstart',e=>dragStart(e,'[data-add]','inventory'));$('furnaceContents').addEventListener('dragstart',e=>dragStart(e,'[data-remove]','furnace'));
for(const [id,to,expected]of [['furnace','furnace','inventory'],['backpack','inventory','furnace']]){const area=$(id);area.addEventListener('dragover',e=>{if(run.state==='lab'&&!dialogType){e.preventDefault();area.classList.add('drag-over')}});area.addEventListener('dragleave',()=>area.classList.remove('drag-over'));area.addEventListener('drop',e=>{e.preventDefault();area.classList.remove('drag-over');try{const data=JSON.parse(e.dataTransfer.getData('application/x-valence'));if(data.from===expected)move(data.id,to)}catch{}})}
$('dialogOverlay').addEventListener('click',e=>{if(e.target===$('dialogOverlay'))closeDialog()});
function moveJoy(e){const r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,n=Math.hypot(dx,dy),s=n>30?30/n:1;joy={x:dx*s/30,y:dy*s/30};$('stick').style.transform=`translate(${dx*s}px,${dy*s}px)`}
$('joystick').addEventListener('pointerdown',e=>{if(run.state!=='playing'||pointer!==null)return;e.preventDefault();pointer=e.pointerId;$('joystick').setPointerCapture(pointer);moveJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===pointer)moveJoy(e)});for(const n of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(n,e=>{if(e.pointerId===pointer)clearInput()});
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(dialogType){if(key==='escape'){e.preventDefault();closeDialog()}if(key==='tab'){const items=[...$('dialogCard').querySelectorAll('button')];if(items.length){let at=items.indexOf(document.activeElement),next=(at+(e.shiftKey?-1:1)+items.length)%items.length;e.preventDefault();items[next].focus()}}return}if(['arrowup','arrowdown','arrowleft','arrowright'].includes(key)&&run.state==='playing')e.preventDefault();if(e.repeat)return;if(key==='enter'&&run.state==='menu'){e.preventDefault();start();return}if(key==='escape'){pause();return}keys[key]=true});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
function autoPause(){clearInput();if(run.state==='playing'){run.state='paused';sync()}}window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)autoPause()});
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000||0));last=now;run.step(dt,{x:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,y:(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y});for(const event of run.events){if(event==='shot')beep(run.lab.gun.type==='water'?240:130,.025,'triangle',.008);if(event==='pickup')beep(750,.035,'sine',.01);if(event==='hurt'){renderer.shake=10;beep(70,.13,'sawtooth',.025)}}run.events=[];if(run.state!=='lab')renderer.draw(run,now/1000);sync();if(now>toastUntil)$('toast').classList.add('hidden');requestAnimationFrame(frame)}
sync();requestAnimationFrame(frame);
